package com.bank.parallelci;

import java.util.concurrent.locks.ReentrantLock;
import java.util.logging.Logger;

// A single shared QA deploy slot. Only one run may deploy at a time.
public class DeploySlot {
    private static final Logger log = Logger.getLogger(DeploySlot.class.getName());
    private final ReentrantLock lock = new ReentrantLock(true); // fair = first-come

    // Equivalent to a Jenkins lock() step or GitHub Actions concurrency group.
    public void deploy(String commit) {
        lock.lock();
        try {
            log.info(() -> "QA slot acquired by " + commit + " -> deploying");
            Thread.sleep(50); // simulate deploy time
            log.info(() -> "QA deploy done for " + commit);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            lock.unlock();
        }
    }
}
