package com.bank.parallelci;

import java.util.concurrent.*;
import java.util.List;
import java.util.logging.Logger;

// One independent pipeline run for one commit. Runs stages in parallel.
public class PipelineRun implements Runnable {
    private static final Logger log = Logger.getLogger(PipelineRun.class.getName());
    private final String commit;
    private final DeploySlot qaSlot;

    public PipelineRun(String commit, DeploySlot qaSlot) {
        this.commit = commit;
        this.qaSlot = qaSlot;
    }

    @Override
    public void run() {
        log.info(() -> "Run started for commit " + commit + " on its own agent");
        runParallelStages();           // independent stages at once
        qaSlot.deploy(commit);         // shared resource -> serialised by lock
        log.info(() -> "Run finished for commit " + commit);
    }

    // Fan-out independent stages, fan-in when all complete.
    private void runParallelStages() {
        List<Callable<String>> stages = List.of(
                () -> stage("unit-tests"),
                () -> stage("integration-tests"),
                () -> stage("security-scan"));
        try (ExecutorService pool = Executors.newFixedThreadPool(3)) {
            List<Future<String>> futures = pool.invokeAll(stages);
            for (Future<String> f : futures) f.get(); // wait for all (fan-in)
        } catch (Exception e) {
            log.severe("Parallel stage failed for " + commit + ": " + e.getMessage());
        }
    }

    private String stage(String name) throws InterruptedException {
        log.info(() -> "  [" + commit + "] stage " + name + " running");
        Thread.sleep(30);
        return name;
    }
}
