package com.bank.parallelci;

import java.util.List;
import java.util.concurrent.*;
import java.util.logging.Logger;

// Expands one job across JDK x service combinations, run in parallel.
public class MatrixBuild {
    private static final Logger log = Logger.getLogger(MatrixBuild.class.getName());

    public void run(List<Integer> jdks, List<String> services, int maxParallel) {
        try (ExecutorService pool = Executors.newFixedThreadPool(maxParallel)) {
            for (int jdk : jdks) {
                for (String svc : services) {
                    final int j = jdk; final String s = svc;
                    pool.submit(() -> log.info(() ->
                            "matrix job: service=" + s + " jdk=" + j + " -> build+test OK"));
                }
            }
        }
    }
}
