package com.bank.parallelci;

import java.util.List;
import java.util.logging.*;

public class ParallelCiDemo {
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new ParallelCiLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws InterruptedException {
        Logger log = Logger.getLogger(ParallelCiDemo.class.getName());
        DeploySlot qaSlot = new DeploySlot();

        log.info("=== Two concurrent pushes -> two independent runs ===");
        Thread rajesh = new Thread(new PipelineRun("rajesh-a1b2", qaSlot));
        Thread priya  = new Thread(new PipelineRun("priya-c3d4", qaSlot));
        rajesh.start();
        priya.start();
        rajesh.join();
        priya.join();

        log.info("=== Matrix build: JDK x service ===");
        new MatrixBuild().run(List.of(17, 21),
                List.of("transfer", "fraud"), 4);
    }
}

